struct Rng(u64);
impl Rng { fn next(&mut self) -> u64 { self.0 = self.0.wrapping_add(0x9E3779B97F4A7C15); let mut z = self.0; z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9); z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB); z ^ (z >> 31) } }
fn gen_Nat(r: &mut Rng, _m: u64) -> u64 { r.next() % 3 }
fn gen_Bool(r: &mut Rng, _m: u64) -> bool { r.next() % 2 == 0 }
fn gen_ListE(r: &mut Rng, m: u64) -> Rc<List<E>> { let k = r.next() % (m + 1); let mut xs = Vec::new(); for _ in 0..k { xs.push(gen_E(r, 3)); } let mut l: Rc<List<E>> = Rc::new(List::Nil); for x in xs.into_iter().rev() { l = Rc::new(List::Con(x, l)); } l }
fn gen_ListLane(r: &mut Rng, m: u64) -> Rc<List<Lane>> { let k = r.next() % (m + 1); let mut xs = Vec::new(); for _ in 0..k { xs.push(gen_Lane(r, 3)); } let mut l: Rc<List<Lane>> = Rc::new(List::Nil); for x in xs.into_iter().rev() { l = Rc::new(List::Con(x, l)); } l }
fn gen_ListOp(r: &mut Rng, m: u64) -> Rc<List<Op>> { let k = r.next() % (m + 1); let mut xs = Vec::new(); for _ in 0..k { xs.push(gen_Op(r, 3)); } let mut l: Rc<List<Op>> = Rc::new(List::Nil); for x in xs.into_iter().rev() { l = Rc::new(List::Con(x, l)); } l }
fn gen_Band(r: &mut Rng, _m: u64) -> Band {
  match r.next() % 3 {
    0 => { Band::Gate }
    1 => { Band::Interactive }
    _ => { Band::Background }
  }
}
fn gen_E(r: &mut Rng, _m: u64) -> E {
  match r.next() % 1 {
    _ => { let f0 = gen_Nat(r, 3); let f1 = gen_Nat(r, 3); let f2 = gen_Nat(r, 3); let f3 = gen_Nat(r, 3); let f4 = gen_Nat(r, 3); E::E(f0, f1, f2, f3, f4) }
  }
}
fn gen_Lane(r: &mut Rng, _m: u64) -> Lane {
  match r.next() % 1 {
    _ => { let f0 = gen_ListE(r, 3); let f1 = gen_ListE(r, 3); Lane::Lane(f0, f1) }
  }
}
fn gen_St(r: &mut Rng, _m: u64) -> St {
  match r.next() % 1 {
    _ => { let f0 = gen_Nat(r, 3); let f1 = gen_Nat(r, 3); let f2 = gen_ListLane(r, 3); St::St(f0, f1, f2) }
  }
}
fn gen_Sp(r: &mut Rng, _m: u64) -> Sp {
  match r.next() % 1 {
    _ => { let f0 = gen_ListE(r, 3); let f1 = gen_ListE(r, 3); Sp::Sp(f0, f1) }
  }
}
fn gen_LS(r: &mut Rng, _m: u64) -> LS {
  match r.next() % 1 {
    _ => { let f0 = gen_Nat(r, 3); let f1 = gen_ListLane(r, 3); LS::LS(f0, f1) }
  }
}
fn gen_LW(r: &mut Rng, _m: u64) -> LW {
  match r.next() % 1 {
    _ => { let f0 = gen_Nat(r, 3); let f1 = gen_Lane(r, 3); LW::LW(f0, f1) }
  }
}
fn gen_W(r: &mut Rng, _m: u64) -> W {
  match r.next() % 1 {
    _ => { let f0 = gen_Nat(r, 3); let f1 = gen_ListE(r, 3); W::W(f0, f1) }
  }
}
fn gen_Pol(r: &mut Rng, _m: u64) -> Pol {
  match r.next() % 2 {
    0 => { Pol::Today }
    _ => { Pol::Spt }
  }
}
fn gen_Op(r: &mut Rng, _m: u64) -> Op {
  match r.next() % 4 {
    0 => { let f0 = gen_Band(r, 3); let f1 = gen_Nat(r, 3); let f2 = gen_Nat(r, 3); let f3 = gen_Nat(r, 3); let f4 = gen_Nat(r, 3); Op::Arrive(f0, f1, f2, f3, f4) }
    1 => { Op::Decide }
    2 => { Op::Tick }
    _ => { let f0 = gen_Nat(r, 3); Op::Finish(f0) }
  }
}

